-- BEGIN db/migrations/137_fix_update_inventory_overload.sql
BEGIN;

-- Fix an ambiguous-overload bug that breaks every inventory-tracked retail sale
-- and refund at runtime.
--
-- Migration 130 added public.update_inventory(..., p_location_id uuid) as a NEW
-- overload. CREATE OR REPLACE only replaces a function with an IDENTICAL argument
-- signature, so adding p_location_id did not replace the 10-argument version from
-- migration 126 — it created a second function. A 10-argument call, as made by
-- record_retail_sale_tx and refund_retail_sale_tx (migration 127):
--
--     PERFORM public.update_inventory(tenant, product, variant, -qty, 'sale',
--             'retail_order', order_id::text, reason, actor, NULL);
--
-- then matches BOTH the 10-arg and the 11-arg overloads (the latter via its
-- p_location_id default), producing:
--
--     ERROR: function public.update_inventory(uuid, uuid, uuid, integer, ...,
--            uuid, unknown) is not unique
--
-- i.e. no POS/retail sale or refund can record inventory. Caught by the live
-- money-path smoke (tests/live-smoke/money-paths-live.smoke.test.ts).
--
-- Fix: drop the superseded 10-argument overload. The 11-argument version
-- (p_location_id DEFAULT NULL, migration 130) already handles 10-argument callers
-- via the default, so every existing call site keeps working and now resolves to a
-- single, unambiguous function.

DROP FUNCTION IF EXISTS public.update_inventory(
  uuid, uuid, uuid, integer, text, text, text, text, uuid, integer
);

COMMIT;
-- END db/migrations/137_fix_update_inventory_overload.sql

-- BEGIN db/migrations/138_harden_retail_sale_functions.sql
-- Hardening for the SECURITY DEFINER retail-sale functions introduced in 127.
-- PostgreSQL grants function EXECUTE to PUBLIC by default; these privileged
-- functions must only be callable by Booka's server-side service role.
BEGIN;

ALTER FUNCTION public.record_retail_sale_tx(uuid, uuid, jsonb, uuid, text, uuid, text, text, text, jsonb)
  SET search_path = pg_catalog, public;
ALTER FUNCTION public.refund_retail_sale_tx(uuid, uuid, uuid, text, text)
  SET search_path = pg_catalog, public;

REVOKE ALL ON FUNCTION public.record_retail_sale_tx(uuid, uuid, jsonb, uuid, text, uuid, text, text, text, jsonb)
  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.refund_retail_sale_tx(uuid, uuid, uuid, text, text)
  FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.record_retail_sale_tx(uuid, uuid, jsonb, uuid, text, uuid, text, text, text, jsonb)
  TO service_role;
GRANT EXECUTE ON FUNCTION public.refund_retail_sale_tx(uuid, uuid, uuid, text, text)
  TO service_role;

COMMIT;
-- END db/migrations/138_harden_retail_sale_functions.sql

-- BEGIN db/migrations/2026-07-31_add_reservations_source.sql
-- Migration: add reservations.source (text)
-- Date: 2026-07-31
--
-- WHY: the public booking path (createPublicBooking) records where a booking
-- came from with `.insert({ ..., source: 'public_booking' })`, but `reservations`
-- has no `source` column on live — the insert errored, so public-page bookings
-- silently failed. Rather than route the origin through metadata only, add the
-- column (useful for booking-origin analytics, parallel to customers.source).
--
-- SAFETY: idempotent (ADD COLUMN IF NOT EXISTS), non-destructive, no RLS change.
-- Backfills existing rows from metadata.booking_source when present. Reviewer
-- runs this; validated in a throwaway postgres:16-alpine container.

BEGIN;

ALTER TABLE public.reservations
  ADD COLUMN IF NOT EXISTS source text;

-- Backfill origin for rows that captured it in metadata while the column was
-- absent. Only where source is still NULL, so re-runs never overwrite.
UPDATE public.reservations
SET source = metadata->>'booking_source'
WHERE source IS NULL
  AND metadata ? 'booking_source'
  AND jsonb_typeof(metadata->'booking_source') = 'string';

COMMIT;

-- Rollback (manual, NOT run automatically):
--   ALTER TABLE public.reservations DROP COLUMN IF EXISTS source;
-- END db/migrations/2026-07-31_add_reservations_source.sql

-- BEGIN db/migrations/2026-08-04_meta_embedded_signup_foundation.sql
-- Meta WhatsApp Embedded Signup foundation
--
-- This migration is additive. It prepares Booka for tenant-owned WABAs and
-- phone numbers connected either through the current operator-assisted Direct
-- Cloud API path or the future Meta Embedded Signup path.
--
-- IMPORTANT:
-- - Do not put raw Meta access tokens in whatsapp_configurations.
-- - New Meta tokens should be stored encrypted in whatsapp_provider_secrets.
-- - Existing api_key values are deliberately not transformed here: encryption
--   must happen in application code using the server-only ENCRYPTION_KEY.

BEGIN;

-- 1. Tenant connection lifecycle. These columns contain identifiers and state,
-- never a Meta access token or payment-card information.
ALTER TABLE public.whatsapp_configurations
  ADD COLUMN IF NOT EXISTS meta_connection_source TEXT,
  ADD COLUMN IF NOT EXISTS meta_connection_status TEXT,
  ADD COLUMN IF NOT EXISTS meta_billing_owner TEXT,
  ADD COLUMN IF NOT EXISTS meta_connected_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS meta_disconnected_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS meta_webhook_subscribed_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS meta_last_validated_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS meta_last_error TEXT;

ALTER TABLE public.whatsapp_configurations
  DROP CONSTRAINT IF EXISTS whatsapp_configurations_meta_connection_source_check,
  ADD CONSTRAINT whatsapp_configurations_meta_connection_source_check
    CHECK (meta_connection_source IS NULL OR meta_connection_source IN ('direct', 'embedded_signup')),
  DROP CONSTRAINT IF EXISTS whatsapp_configurations_meta_connection_status_check,
  ADD CONSTRAINT whatsapp_configurations_meta_connection_status_check
    CHECK (meta_connection_status IS NULL OR meta_connection_status IN (
      'pending', 'connected', 'action_required', 'disconnected', 'revoked', 'failed'
    )),
  DROP CONSTRAINT IF EXISTS whatsapp_configurations_meta_billing_owner_check,
  ADD CONSTRAINT whatsapp_configurations_meta_billing_owner_check
    CHECK (meta_billing_owner IS NULL OR meta_billing_owner IN ('client', 'booka'));

-- Existing active Meta mappings are known operator-assisted connections.
UPDATE public.whatsapp_configurations
SET
  meta_connection_source = COALESCE(meta_connection_source, 'direct'),
  meta_connection_status = COALESCE(meta_connection_status, 'connected'),
  meta_billing_owner = COALESCE(meta_billing_owner, 'client'),
  meta_connected_at = COALESCE(meta_connected_at, updated_at, created_at, NOW())
WHERE provider = 'meta'
  AND active = true
  AND meta_phone_number_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_whatsapp_configurations_meta_connection_status
  ON public.whatsapp_configurations (meta_connection_status)
  WHERE provider = 'meta';

-- 2. Encrypted Meta credential envelope. `api_key` remains nullable only for
-- encrypted rows and legacy rows; application code must prefer encrypted_api_key.
ALTER TABLE public.whatsapp_provider_secrets
  ALTER COLUMN api_key DROP NOT NULL,
  ADD COLUMN IF NOT EXISTS encrypted_api_key TEXT,
  ADD COLUMN IF NOT EXISTS encryption_iv TEXT,
  ADD COLUMN IF NOT EXISTS encryption_key_version TEXT,
  ADD COLUMN IF NOT EXISTS token_scopes JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS last_validated_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS revoked_at TIMESTAMPTZ;

ALTER TABLE public.whatsapp_provider_secrets
  DROP CONSTRAINT IF EXISTS whatsapp_provider_secrets_encrypted_key_check,
  ADD CONSTRAINT whatsapp_provider_secrets_encrypted_key_check
    CHECK (
      (encrypted_api_key IS NULL AND encryption_iv IS NULL AND encryption_key_version IS NULL)
      OR
      (encrypted_api_key IS NOT NULL AND encryption_iv IS NOT NULL AND encryption_key_version IS NOT NULL)
    );

-- 3. Append-only, token-free audit trail for provisioning and disconnection.
CREATE TABLE IF NOT EXISTS public.tenant_meta_connection_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL CHECK (event_type IN (
    'connection_started', 'connection_connected', 'connection_failed',
    'webhook_subscribed', 'credential_rotated', 'connection_disconnected',
    'connection_revoked', 'validation_failed'
  )),
  connection_source TEXT CHECK (connection_source IN ('direct', 'embedded_signup')),
  actor_user_id UUID,
  meta_waba_id TEXT,
  meta_phone_number_id TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT tenant_meta_connection_events_no_credentials
    CHECK (NOT (metadata ? 'access_token') AND NOT (metadata ? 'api_key'))
);

CREATE INDEX IF NOT EXISTS idx_tenant_meta_connection_events_tenant_created
  ON public.tenant_meta_connection_events (tenant_id, created_at DESC);

ALTER TABLE public.tenant_meta_connection_events ENABLE ROW LEVEL SECURITY;

-- This is a server-only audit table. Tenant owners receive a redacted status
-- through Booka API routes; they must never read credentials or raw Meta events.
REVOKE ALL ON TABLE public.tenant_meta_connection_events FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.tenant_meta_connection_events TO service_role;

COMMIT;
-- END db/migrations/2026-08-04_meta_embedded_signup_foundation.sql

-- BEGIN db/migrations/2026-08-10_storefront_engine.sql
-- Public Storefront Engine: queryable campaigns + privacy-minimised funnel events.
CREATE TABLE IF NOT EXISTS public.storefront_campaigns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','active','paused','expired','superseded')),
  title text NOT NULL, copy text, cta_label text, target_type text, target_ids jsonb NOT NULL DEFAULT '[]'::jsonb,
  start_at timestamptz NOT NULL DEFAULT now(), end_at timestamptz, source text NOT NULL DEFAULT 'owner', approval_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (end_at IS NULL OR end_at > start_at)
);
CREATE INDEX IF NOT EXISTS idx_storefront_campaigns_active ON public.storefront_campaigns (tenant_id, status, start_at DESC);
CREATE TABLE IF NOT EXISTS public.storefront_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  event_type text NOT NULL CHECK (event_type IN ('storefront_view','service_view','product_view','cta_click','ask_booka_opened','booking_started','booking_completed','product_added','checkout_started','purchase_completed','campaign_view','campaign_conversion')),
  page_type text NOT NULL CHECK (page_type IN ('storefront','service','product','campaign')), session_id uuid, service_id uuid REFERENCES public.services(id) ON DELETE SET NULL, product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, campaign_id uuid REFERENCES public.storefront_campaigns(id) ON DELETE SET NULL,
  referrer text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_storefront_events_funnel ON public.storefront_events (tenant_id, event_type, created_at DESC);
ALTER TABLE public.storefront_campaigns ENABLE ROW LEVEL SECURITY; ALTER TABLE public.storefront_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS storefront_campaigns_tenant_access ON public.storefront_campaigns; CREATE POLICY storefront_campaigns_tenant_access ON public.storefront_campaigns FOR ALL USING (tenant_id IN (SELECT tenant_id FROM public.tenant_users WHERE user_id = auth.uid()));
DROP POLICY IF EXISTS storefront_events_tenant_access ON public.storefront_events; CREATE POLICY storefront_events_tenant_access ON public.storefront_events FOR SELECT USING (tenant_id IN (SELECT tenant_id FROM public.tenant_users WHERE user_id = auth.uid()));
-- END db/migrations/2026-08-10_storefront_engine.sql